def f(g):
    h,w=len(g),len(g[0])
    o=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            grp=[g[i][j],g[i][w-1-j],g[h-1-i][j],g[h-1-i][w-1-j]]
            nz=[v for v in grp if v!=2]
            if len(set(grp))>1 and nz:
                o[i][j]=Counter(nz).most_common(1)[0][0]
            elif not nz:
                o[i][j]=g[j][i] if g[j][i]!=2 else g[h-1-j][w-1-i]
    return o
